-- PT110-S2-Q2. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT110-S2-Q2$batch13$ AND q.stimulus=$batch13$Having an efficient, attractive subway system makes good economic sense. So, the city needs to purchase new subway cars, since the city should always do what makes good economic sense.$batch13$ AND q.prompt=$batch13$The conclusion drawn above follows logically if which one of the following is assumed?$batch13$ AND q.correct_choice=$batch13$E$batch13$) THEN RAISE EXCEPTION 'Question changed: PT110-S2-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT110-S2-Q2$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S2-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT110-S2-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The city needs to buy new subway cars.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$An efficient, attractive subway system makes good economic sense. The city should always do what makes good economic sense.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The premises get us to "the city should have an efficient, attractive subway system". The conclusion jumps to new subway cars. The gap is the link between the two.$batch13$), (3, $batch13$Goal$batch13$, $batch13$New subway cars are needed for an efficient, attractive system.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT110-S2-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The premises already give us this. It doesn't mention new cars.$batch13$), ($batch13$B$batch13$, $batch13$Cost-effective cars being part of an efficient system doesn't require new ones.$batch13$), ($batch13$C$batch13$, $batch13$Beating many other investments doesn't make buying new cars required.$batch13$), ($batch13$D$batch13$, $batch13$Being affordable doesn't make new cars needed.$batch13$), ($batch13$E$batch13$, $batch13$If new cars are required for the system the city should have, the city needs new cars.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT110-S2-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
